'''
CLI application for monitoring CPU usage per process, similar to a simplified `top` command.
'''
import time
import psutil
import argparse
def get_process_info():
    '''
    Retrieves a list of tuples containing process ID, name, and CPU usage percentage for all processes.
    '''
    process_info = []
    for proc in psutil.process_iter(['pid', 'name', 'cpu_percent']):
        try:
            process_info.append((proc.info['pid'], proc.info['name'], proc.info['cpu_percent']))
        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
            pass
    return process_info
def get_process_info_by_pid(pid):
    '''
    Retrieves a tuple containing process ID, name, and CPU usage percentage for a specific process identified by PID.
    '''
    try:
        proc = psutil.Process(pid)
        return (proc.pid, proc.name(), proc.cpu_percent())
    except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
        return None
def display_process_info(process_info):
    '''
    Displays the process information in a tabular format.
    '''
    print(f"{'PID':<10}{'Name':<25}{'CPU Usage (%)':<15}")
    print("="*50)
    for pid, name, cpu in process_info:
        print(f"{pid:<10}{name:<25}{cpu:<15}")
def main():
    parser = argparse.ArgumentParser(description="CLI CPU Usage Monitor")
    parser.add_argument('--pid', type=int, help='Focus on a specific process by PID')
    args = parser.parse_args()
    while True:
        if args.pid:
            process_info = get_process_info_by_pid(args.pid)
            if process_info:
                display_process_info([process_info])
            else:
                print(f"No process found with PID {args.pid}")
        else:
            process_info = get_process_info()
            display_process_info(process_info)
        time.sleep(2)
if __name__ == "__main__":
    main()
